/* S20 shop effects: one fixed script (hashed in the page's CSP). Everything here only ENHANCES the page: with JavaScript
   off, the menu, the quantity boxes and the order form work exactly as before. Reduced motion: no movement at all.
   Built only from the page's own elements with textContent/cloneNode (no HTML strings). Animations use transform and
   opacity; layout is read once per click or per observer callback, never inside an animation frame. */
(function () {
  try {
    var form = document.getElementById("order-form");
    if (!form) return;
    var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    var hasIO = "IntersectionObserver" in window;
    var rows = Array.prototype.slice.call(form.querySelectorAll(".item"));
    var bar = document.getElementById("bar-order");

    /* ---- add to basket: a dot flies to the basket, which bumps ---- */
    function target() {
      var bl = bar && bar.getElementsByTagName("a")[0];
      if (bl && bl.offsetParent !== null) return bl;
      return document.getElementById("order-h");
    }
    function fly(from) {
      if (reduce || !from || !from.animate) return;
      var t = target();
      if (!t) return;
      var a = from.getBoundingClientRect(), b = t.getBoundingClientRect();
      var x0 = a.left + a.width / 2 - 7, y0 = a.top + a.height / 2 - 7, x1 = b.left + b.width / 2 - 7, y1 = b.top + b.height / 2 - 7;
      var dot = document.createElement("span");
      dot.className = "fly"; dot.setAttribute("aria-hidden", "true");
      document.body.appendChild(dot);
      var up = Math.max(30, Math.abs(y1 - y0) * 0.35);
      var run = dot.animate([
        { transform: "translate(" + x0 + "px," + y0 + "px) scale(1)", opacity: 1 },
        { transform: "translate(" + (x0 + (x1 - x0) * 0.5) + "px," + (Math.min(y0, y1) - up) + "px) scale(1.15)", opacity: 1, offset: 0.5 },
        { transform: "translate(" + x1 + "px," + y1 + "px) scale(.4)", opacity: 0.2 }
      ], { duration: 520, easing: "cubic-bezier(.3,.7,.3,1)" });
      run.onfinish = function () {
        if (dot.parentNode) dot.parentNode.removeChild(dot);
        if (t.animate) t.animate([{ transform: "scale(1)" }, { transform: "scale(1.1)" }, { transform: "scale(1)" }], { duration: 300, easing: "ease-out" });
      };
      if (navigator.vibrate) { try { navigator.vibrate(8); } catch (e) { /* not allowed: fine */ } }
    }
    rows.forEach(function (row) {
      var add = row.querySelector(".add"), plus = row.querySelector(".plus");
      if (add) add.addEventListener("click", function () { fly(add); });
      if (plus) plus.addEventListener("click", function () { fly(plus); });
    });

    /* ---- quick view: a sheet with the item's own details; its stepper drives the real quantity box ---- */
    var dlg = document.createElement("dialog");
    if (typeof dlg.showModal === "function") {
      dlg.className = "qv"; dlg.setAttribute("aria-label", "Item details");
      document.body.appendChild(dlg);
      var current = null;
      var open = function (row) {
        current = row;
        while (dlg.firstChild) dlg.removeChild(dlg.firstChild);
        var body = document.createElement("div"); body.className = "qv-body";
        var img = row.querySelector(".item-photo, .thumb img");
        if (img) {
          var big = document.createElement("img");
          big.src = img.src.replace(/-480\.webp$/, "-1200.webp"); big.alt = img.alt || "";
          body.appendChild(big);
        }
        var h = document.createElement("h3"); h.textContent = row.querySelector("input").dataset.name; body.appendChild(h);
        var nb = row.querySelector(".new-badge"); if (nb) body.appendChild(nb.cloneNode(true));
        var fm = row.querySelector(".fm-row"); if (fm) body.appendChild(fm.cloneNode(true));
        var d = row.querySelector(".desc"); if (d) { var p = document.createElement("p"); p.textContent = d.textContent; body.appendChild(p); }
        var pr = document.createElement("div"); pr.className = "qv-price"; pr.textContent = row.querySelector(".price").textContent; body.appendChild(pr);
        var line = document.createElement("div"); line.className = "qv-row";
        var minus = document.createElement("button"); minus.type = "button"; minus.className = "btn btn-line btn-sm"; minus.textContent = "−"; minus.setAttribute("aria-label", "One less");
        var out = document.createElement("output"); out.setAttribute("aria-live", "polite");
        var plus = document.createElement("button"); plus.type = "button"; plus.className = "btn btn-line btn-sm"; plus.textContent = "+"; plus.setAttribute("aria-label", "One more");
        var add = document.createElement("button"); add.type = "button"; add.className = "btn btn-primary btn-sm"; add.textContent = "Add to order";
        line.appendChild(minus); line.appendChild(out); line.appendChild(plus); line.appendChild(add); body.appendChild(line);
        var close = document.createElement("button"); close.type = "button"; close.className = "btn btn-line btn-sm qv-close"; close.textContent = "Close";
        body.appendChild(close);
        var input = row.querySelector("input");
        var sync = function () { out.textContent = String(parseInt(input.value, 10) || 0); };
        var bump = function (btn, which) { var b = row.querySelector(which); if (b) b.click(); sync(); if (btn === add || btn === plus) fly(btn); };
        minus.addEventListener("click", function () { if ((parseInt(input.value, 10) || 0) > 0) bump(minus, ".minus"); });
        plus.addEventListener("click", function () { bump(plus, (parseInt(input.value, 10) || 0) ? ".plus" : ".add"); });
        add.addEventListener("click", function () { bump(add, (parseInt(input.value, 10) || 0) ? ".plus" : ".add"); });
        close.addEventListener("click", function () { dlg.close(); });
        sync();
        dlg.appendChild(body);
        dlg.showModal();
      };
      dlg.addEventListener("click", function (e) { if (e.target === dlg) dlg.close(); });
      dlg.addEventListener("close", function () { var r = current; current = null; if (r) { var b = r.querySelector(".qv-open"); if (b) b.focus(); } });
      rows.forEach(function (row) {
        var main = row.querySelector(".item-main");
        if (!main) return;
        var b = document.createElement("button");
        b.type = "button"; b.className = "qv-open"; b.textContent = "Details"; b.setAttribute("aria-haspopup", "dialog");
        main.appendChild(b);
        b.addEventListener("click", function () { open(row); });
        row.addEventListener("click", function (e) {
          if (e.target.closest && e.target.closest(".qty, a, button, input, label")) return;
          open(row);
        });
      });
    }

    /* ---- category bar follows the scroll ---- */
    var chips = Array.prototype.slice.call(document.querySelectorAll(".chips .chip"));
    var cats = Array.prototype.slice.call(document.querySelectorAll(".cat[id^='cat-']"));
    if (hasIO && chips.length && cats.length) {
      var spy = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (!en.isIntersecting) return;
          chips.forEach(function (c) {
            var on = c.getAttribute("href") === "#" + en.target.id;
            if (on) c.setAttribute("aria-current", "true"); else c.removeAttribute("aria-current");
            if (on && c.parentNode && c.parentNode.parentNode) {
              var box = c.parentNode.parentNode;
              if (box.scrollWidth > box.clientWidth) box.scrollLeft = c.offsetLeft - box.clientWidth / 2 + c.offsetWidth / 2;
            }
          });
        });
      }, { rootMargin: "-25% 0px -65% 0px" });
      cats.forEach(function (c) { spy.observe(c); });
    }

    /* ---- gentle reveal; the motif rests while off screen; a New badge shines once ---- */
    var wrap = document.querySelector(".motif-wrap");
    if (hasIO && wrap) {
      new IntersectionObserver(function (en) { wrap.classList.toggle("off", !en[0].isIntersecting); }).observe(wrap);
    }
    if (hasIO && !reduce) {
      var seen = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (!en.isIntersecting) return;
          en.target.classList.add("in"); seen.unobserve(en.target);
        });
      }, { rootMargin: "0px 0px -8% 0px" });
      Array.prototype.forEach.call(document.querySelectorAll(".cat, .gallery, .how .step, .tile"), function (el) {
        if (el.getBoundingClientRect().top < window.innerHeight) return; /* already in view at load: leave it be */
        el.classList.add("pre"); seen.observe(el);
      });
      var shine = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add("shine"); shine.unobserve(en.target); } });
      });
      Array.prototype.forEach.call(document.querySelectorAll(".new-badge"), function (el) { shine.observe(el); });
    }
  } catch (e) { /* the page works without any of this */ }
})();
  /* S20: each shop's signature (motif layer in the hero) and the gentle interactions. Transform and opacity only: nothing
     here animates filters, blur, shadows, radii or layout. With reduced motion everything is still. */
  .hero { position: relative; isolation: isolate; }
  .motif-wrap { position: absolute; inset: 0; z-index: -1; overflow: hidden; pointer-events: none; color: var(--accent); opacity: .08; contain: paint; }
  .motif { position: absolute; left: -3%; top: -3%; width: 106%; height: 106%; }
  /* S20B: the clearly visible part of the signature: a strip under the hero with NO text in it (text never sits on it, so
     it can be strong); faded at both ends. The layer behind the hero text above stays faint (.08, the AA test). */
  .motif-band { height: 56px; margin: 18px 0 2px; color: var(--accent); opacity: .3; overflow: hidden; pointer-events: none;
    -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent); mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent); }
  .motif-band .band { display: block; width: 100%; height: 100%; }
  @media (min-width: 900px) { .motif-band { height: 72px; margin-top: 30px; } }
  .motif-thumb { display: block; width: 100%; height: auto; color: var(--accent); }
  @keyframes lw-drift { 0%, 100% { transform: translate3d(0, 0, 0); } 50% { transform: translate3d(-1.6%, 1.8%, 0); } }
  @keyframes lw-sway { 0%, 100% { transform: rotate(0deg); } 50% { transform: rotate(1.4deg); } }
  @keyframes lw-bob { 0%, 100% { transform: translate3d(0, 0, 0); } 50% { transform: translate3d(0, -2.2%, 0); } }
  @keyframes lw-shine { from { transform: translateX(-130%); } to { transform: translateX(130%); } }
  @keyframes lw-sheet { from { transform: translateY(26px); opacity: 0; } to { transform: none; opacity: 1; } }
  @media (prefers-reduced-motion: no-preference) {
    .motion-drift .motif { animation: lw-drift 30s ease-in-out infinite; will-change: transform; }
    .motion-sway .motif { animation: lw-sway 34s ease-in-out infinite; will-change: transform; }
    .motion-bob .motif { animation: lw-bob 22s ease-in-out infinite; will-change: transform; }
    .motif-wrap.off .motif { animation-play-state: paused; will-change: auto; }
    .js .pre { opacity: 0; transform: translate3d(0, 14px, 0); }
    .js .pre.in { opacity: 1; transform: none; transition: opacity .55s ease, transform .55s ease; }
    .new-badge { position: relative; overflow: hidden; }
    .new-badge.shine::after { content: ""; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 30%, rgba(255,255,255,.6) 50%, transparent 70%); animation: lw-shine .9s ease 1 both; }
    dialog.qv[open] { animation: lw-sheet .26s ease-out; }
  }
  .fly { position: fixed; left: 0; top: 0; width: 14px; height: 14px; border-radius: 50%; background: var(--accent); z-index: 80; pointer-events: none; }
  .chips { position: sticky; top: 0; z-index: 15; background: var(--bg); padding-top: 8px; }
  .chips a.on, .chips a[aria-current="true"] { background: var(--accent); color: var(--accent-ink); }
  .cat { scroll-margin-top: 64px; }
  .js .item-main { cursor: pointer; }
  .qv-open { background: none; border: 0; padding: 2px 0; margin-top: 4px; color: var(--accent); font: inherit; font-size: 13px; font-weight: 650; text-decoration: underline; cursor: pointer; }
  dialog.qv { border: 0; padding: 0; width: min(520px, 94vw); max-height: 88vh; overflow: auto; border-radius: var(--radius); background: var(--paper); color: var(--ink); }
  dialog.qv::backdrop { background: rgba(0, 0, 0, .5); }
  @media (max-width: 640px) { dialog.qv { width: 100%; max-width: 100%; margin: auto 0 0; border-radius: 18px 18px 0 0; } }
  .qv-body { padding: 18px 20px 22px; display: grid; gap: 10px; }
  .qv-body img { width: 100%; height: auto; max-height: 46vh; object-fit: cover; border-radius: var(--radius-sm, 10px); }
  .qv-body h3 { font-family: var(--display); font-size: 24px; line-height: 1.15; margin: 0; }
  .qv-price { font-weight: 700; font-variant-numeric: tabular-nums; }
  .qv-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  .qv-row output { min-width: 2ch; text-align: center; font-weight: 700; }
  .qv-close { justify-self: end; }
