      {user?.status === "pending" && <PendingNote />}
      {!user && <GuestNote />}
      {shops.length === 0 ? (
        <section className="card">
          <p>No shops yet.</p>
          <a className="btn btn-primary" href={user ? "#/new" : "#/try"}>
            Describe your business
          </a>
        </section>
      ) : (
        <ul className="names shops">
          {shops.map((b) => (
            <li key={b.id}>
              <span>
                <a href={`#/b/${b.id}`}>
                  <strong>{b.name}</strong>
                </a>
                {b.live_url && (
                  <>
                    <br />
                    <span className="small muted shop-address">{new URL(b.live_url).host}</span>
                  </>
                )}
                <br />
                <span className="muted">{shopState(b)}</span>
                {b.pending_edit && (
