              {KINDS.map(([k, label]) => (
                <option key={k} value={k}>
                  {label}
                </option>
              ))}
            </select>
            <small>Your shop shows “from ₹{Math.min(...options.map((o) => o.price_inr || Infinity)) || 0}” and a box for each size.</small>
          </label>
        )}
      </fieldset>
      <div className="sell-row">
        <label className="field">
          <span>Price is</span>
          <select value={p.unit ?? ""} onChange={(e) => onChange({ unit: e.target.value as Product["unit"] })}>
            {UNITS.map(([k, label]) => (
              <option key={k} value={k}>
                {label}
              </option>
            ))}
          </select>
        </label>
        <label className="field price">
          <span>Minimum order</span>
          <input
            type="number"
            inputMode="numeric"
            min={1}
            max={100}
            value={p.min_qty ?? 1}
            onChange={(e) => onChange({ min_qty: whole(e.target.value, 1, 100) })}
          />
        </label>
        <label className="field price">
          <span>Maximum (0 = no limit)</span>
          <input
            type="number"
            inputMode="numeric"
            min={0}
            max={100}
            value={p.max_qty ?? 0}
            onChange={(e) => onChange({ max_qty: whole(e.target.value, 0, 100) })}
          />
        </label>
        <label className="field price">
